--
-- TOC entry 289 (class 1255 OID 17076)
-- Name: check_booking_overlap(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_booking_overlap() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  overlap_count INTEGER;
BEGIN
  -- Check ANY overlapping booking regardless of user
  SELECT COUNT(*)
  INTO overlap_count
  FROM bookings
  WHERE vehicle_id = NEW.vehicle_id
  AND status IN ('pending_payment', 'confirmed', 'ongoing')
  AND id != COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
  AND (
    -- Standard overlap condition
    NEW.pickup_date <= return_date 
    AND NEW.return_date >= pickup_date
  );
  
  IF overlap_count > 0 THEN
    RAISE EXCEPTION 'DOUBLE_BOOKING: Vehicle already booked for overlapping dates';
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.check_booking_overlap() OWNER TO postgres;

--
-- TOC entry 288 (class 1255 OID 17065)
-- Name: update_vehicle_rating(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_vehicle_rating() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE vehicles 
    SET average_rating = (
        SELECT ROUND(AVG(rating)::numeric, 1)
        FROM reviews 
        WHERE vehicle_id = COALESCE(NEW.vehicle_id, OLD.vehicle_id)
        AND is_public = true
    ),
    total_bookings = (
        SELECT COUNT(*)
        FROM bookings 
        WHERE vehicle_id = COALESCE(NEW.vehicle_id, OLD.vehicle_id)
        AND status = 'completed'
    )
    WHERE id = COALESCE(NEW.vehicle_id, OLD.vehicle_id);
    
    RETURN COALESCE(NEW, OLD);
END;
$$;


