--
-- TOC entry 240 (class 1259 OID 17060)
-- Name: vehicle_ratings_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vehicle_ratings_summary AS
 SELECT vehicle_id,
    count(*) AS total_reviews,
    round(avg(rating), 1) AS average_rating,
    count(
        CASE
            WHEN (rating = 5) THEN 1
            ELSE NULL::integer
        END) AS five_star,
    count(
        CASE
            WHEN (rating = 4) THEN 1
            ELSE NULL::integer
        END) AS four_star,
    count(
        CASE
            WHEN (rating = 3) THEN 1
            ELSE NULL::integer
        END) AS three_star,
    count(
        CASE
            WHEN (rating = 2) THEN 1
            ELSE NULL::integer
        END) AS two_star,
    count(
        CASE
            WHEN (rating = 1) THEN 1
            ELSE NULL::integer
        END) AS one_star
   FROM public.reviews r
  WHERE (is_public = true)
  GROUP BY vehicle_id;


ALTER VIEW public.vehicle_ratings_summary OWNER TO postgres;

